import pandas as pd
import numpy as np

class BreakoutDetectionStrategy:
    def __init__(self, data):
        self.data = data
        self.cci = self.calculate_cci()
        self.atr = self.calculate_atr()
        self.ma = self.calculate_ma()
        self.macd = self.calculate_macd()

    def calculate_cci(self):
        # Calculate Commodity Channel Index (CCI)
        cci = (self.data['Close'] - self.data['Close'].rolling(window=14).mean()) / (0.015 * self.data['Close'].rolling(window=14).std())
        return cci

    def calculate_atr(self):
        # Calculate Average True Range (ATR)
        high_low = self.data['High'] - self.data['Low']
        high_close = np.abs(self.data['High'] - self.data['Close'].shift(1))
        low_close = np.abs(self.data['Low'] - self.data['Close'].shift(1))
        ranges = pd.concat([high_low, high_close, low_close], axis=1)
        atr = ranges.max(axis=1).rolling(window=14).mean()
        return atr

    def calculate_ma(self):
        # Calculate Moving Average (MA)
        ma = self.data['Close'].rolling(window=50).mean()
        return ma

    def calculate_macd(self):
        # Calculate Moving Average Convergence Divergence (MACD)
        ema_12 = self.data['Close'].ewm(span=12, adjust=False).mean()
        ema_26 = self.data['Close'].ewm(span=26, adjust=False).mean()
        macd = ema_12 - ema_26
        macd_signal = macd.ewm(span=9, adjust=False).mean()
        return macd, macd_signal

    def generate_signals(self):
        signals = pd.DataFrame(index=self.data.index)
        signals['entry'] = 0
        signals['exit'] = 0

        # Bullish breakout
        signals.loc[(self.cci > 100) & (self.macd > self.macd_signal), 'entry'] = 1

        # Bearish breakout
        signals.loc[(self.cci < -100) & (self.macd < self.macd_signal), 'entry'] = -1

        # Bullish exit
        signals.loc[(self.cci < -100) | (self.macd < self.macd_signal), 'exit'] = -1

        # Bearish exit
        signals.loc[(self.cci > 100) | (self.macd > self.macd_signal), 'exit'] = 1

        return signals

    def calculate_position_size(self):
        # Calculate position size based on risk percentage
        risk_percentage = 0.02
        position_size = (risk_percentage * self.data['Close']) / self.atr
        return position_size

    def calculate_stop_loss(self):
        # Calculate stop loss based on percentage
        stop_loss_percentage = 0.05
        stop_loss = self.data['Close'] * (1 - stop_loss_percentage)
        return stop_loss

